mapper.select:
SELECT r.id AS report_id, r.session_id, r.scoring_rule_version, r.total_score, r.dimension_scores_json, r.generated_at FROM interview_report r JOIN interview_session s ON s.id = r.session_id WHERE s.user_id = #{userId} AND r.status = 'REPORT_READY' AND r.scoring_rule_version = #{ruleVersion}
AND r.generated_at >= DATE_SUB(UTC_TIMESTAMP(6), INTERVAL #{days} DAY)
ORDER BY r.generated_at ASC, r.id ASC LIMIT 500
